import{_ as n,a0 as l,w as a,s as p,ao as d,I as o,x as t,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"10個開源的基於WEB的文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"10個開源的基於WEB的文件管理器 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10個開源的基於WEB的文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10個開源的基於WEB的文件管理器 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/10 Useful Open Source Web Based File Managers","title":"10個開源的基於WEB的文件管理器","tag":"201402","desc":""},"relativePath":"201402/10 Useful Open Source Web Based File Managers.md","filePath":"[post].md"}'),g={name:"201402/10 Useful Open Source Web Based File Managers.md"};function u(m,e,f,P,T,C){const r=l("Link");return a(),p("div",null,[e[11]||(e[11]=d('<h1 id="_10個開源的基於web的文件管理器" tabindex="-1">10個開源的基於WEB的文件管理器 <a class="header-anchor" href="#_10個開源的基於web的文件管理器" aria-label="Permalink to “10個開源的基於WEB的文件管理器”">​</a></h1><p>目前，隨着因特網的廣泛普及，對文件管理的需求變得更多。對很多人來説，用一個應用程序來有效管理你在網絡上的文件是必不可少的。因此，下面列出你會用到的10個最好的開源的基於WEB的文件管理器。</p><p><img src="http://www.efytimes.com/admin/useradmin/photo/xBds51300PM1102014.jpg" alt=""></p><ol><li><p><strong>eXtplorer</strong>: 這個程序為你提供了移動、複製、編輯、搜索、刪除、下載和上傳功能。此外，你也能用 eXtplorer 創建和提取檔案，文件夾和新文件。它的主要功能是讓你通過 FTP 訪問文件。你可以選擇 Mozilla 公共許可或者 GPL 協議。為了正常使用這個文件管理器，服務器的PHP最低版本要求為 PHP 4.3 並且必須更新JavaScript。</p></li><li><p><strong>AjaXplorer</strong>: 絕大多數瀏覽器都支持這個文件管理器，並且它能很輕易地自動適應類似於手機一樣的小屏幕瀏覽。目前iOS版的程序已經被開發出來了，安卓版的也將很快完成。要運行 AjaXplorer:，你所需要的是一個支持 PHP5.1 或者更高版本的WEB服務器來。它允許你直接從服務器流式傳輸視頻內容。</p></li><li><p><strong>KFM</strong>: 這個免費和開源文件管理器可以作為 FCKedition、CKeditor、Tiny MCE 之類的富文本編輯器的插件。如果您正在使用一個基於 Linux 的操作系統，那麼你需要 PHP 5.2 或更高版本，而 Mac OS X 和 Windows 分別需要 MySQL 4.1 或更高版本和 MySQL 5.0 或更高版本。它有一個自己的搜索引擎，附帶了一個文本編輯器，可以高亮顯示語法。它還帶有 mp3 播放和視頻播放選項。</p></li><li><p><strong>PAFM</strong>: 這個文件管理器可以讓用户完全控制文件，還允許使用 CodePress 來編輯源代碼。文件管理器的主要特色來自 CodePress，它提供了即時的語法高亮顯示。</p></li><li><p><strong>QuiXplorer</strong>: 這個文件管理器可用於在互聯網和局域網管理和共享文件。它還提供了一種多用户模式，每個用户可以定製自己的設置。</p></li><li><p><strong>BytesFall</strong> Explorer: 這個使用 PHP 和 JavaScript 編寫的管理器在 GPL 下發布。它的 UI 非常類似於 Windows 資源管理器，但是它被用在 GeSHi、LiveTree、Shell 命令、FCKeditor 等項目。因為它有一組不同的功能。</p></li><li><p><strong>NavPHP</strong>: 這個文件管理器是使用PHP和AJAX編寫的，並且提供了WindowsXP風格的導航。和 QuiXplorer 一樣，這個管理器也有一個多用户模式，並有自己的代碼編輯器。此外，它還可以使用Deflate和Gzip來壓縮傳輸網頁。你也可以使用這個功能來以zip格式下載文件或文件夾。</p></li><li><p><strong>iDC File Manager</strong>: 這是一個多用户系統，可以安裝在基於 Linux 或 Windows 的網頁服務器上。它提供了熱鍵功能並支持社交網絡，還可以監視用户活動。它的資料庫是 MySQL。</p></li><li><p><strong>FileMan</strong>: 這個文件管理器帶有一個所見即所得編輯器，可以編輯和創建 HTML 文件。除了 HTML 編輯器,它還具有其他很多有用的功能。</p></li><li><p><strong>Relay</strong>: 這個文件管理器使用 GPL 協議發佈，並支持 AJAX。如果你使用大量的目錄和文件,那麼這個管理器對你來説非常理想。</p></li></ol><hr>',5)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),s(r,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=126569"},{default:i(()=>[...e[0]||(e[0]=[t("http://www.efytimes.com/e1/fullnews.asp?edid=126569",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("譯者：",-1)),s(r,{href:"https://github.com/kingname"},{default:i(()=>[...e[2]||(e[2]=[t("kingname",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),s(r,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...e[3]||(e[3]=[t("Caroline",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),s(r,{href:"http://linux.cn/"},{default:i(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const B=n(g,[["render",u]]);export{w as __pageData,B as default};
